 return {'PD-reference':'PD reference','LQR-oracle':'Velocity oracle','FD-reference':'FD reference','C-legacy-units':'cKF legacy','C-correct-units':'cKF units fixed','C-causal-base':'cKF causal','dLQG-base':'dKF base','KF-LQR-base':'dKF continuous K','delay-aware-base':'Predictor base','delay-aware-tuned':'Predictor selected'}.get(s,s)
