eq('delay',sub(V('y'),V('k')),O('='),V('C'),V('z'),O('('),sub(V('t'),V('k')),O('−'),V('τ'),O(')'),O('+'),sub(V('v'),V('k')))
eq('predict',sub(f.hat(V('z')),V('k')),O('='),sup(V('F'),V('q')),sub(f.hat(V('z')),V('k−q|k')),O('+'),f.tag('munderover',O('∑')+R(V('h'),O('='),N(0))+R(V('q'),O('−'),N(1))),sup(V('F'),V('h')),V('G'),sub(V('u'),V('k−1−h')))
eq('margin',sub(V('τ'),V('PM')),O('='),sub(V('min'),V('i')),frac(sub(V('φ'),V('mi')),sub(V('ω'),V('gci'))))
eq('d50',sub(V('D'),N(50)),O('='),V('inf'),O('{'),V('τ'),O('≥'),N(0),O(':'),sub(V('p'),V('T')),O('('),V('τ'),O(')'),O('<'),frac(N(1),N(2)),O('}'))
eq('memory',sub(V('h'),V('k+1')),O('='),V('α'),sub(V('h'),V('k')),O('+'),O('('),N(1),O('−'),V('α'),O(')'),sub(V('y'),V('k')))
eq('velocity',sub(f.hat(V('v')),V('k')),O('='),frac(R(N(1),O('−'),V('α')),f.TS),O('('),sub(V('y'),V('k')),O('−'),sub(V('h'),V('k')),O(')'))
eq('ky',sub(V('K'),V('y')),O('='),sub(V('K'),V('p')),O('+'),frac(R(N(1),O('−'),V('α')),f.TS),sub(V('K'),V('v')))
eq('kh',sub(V('K'),V('h')),O('='),O('−'),frac(R(N(1),O('−'),V('α')),f.TS),sub(V('K'),V('v')))
